            {
                yield return item;
            }
            if (queryCategories.HasFlag(AssetLinkQuery.Listed))
            {
                if (obj.LargeIconFilename != null)
                {
                    yield return obj.LargeIconFilename;
                }
                if (obj.SmallIconFilename != null)
                {
                    yield return obj.SmallIconFilename;
                }
            }
            yield break;
        }
        
